-- stray – englische Texte (Teil 36), Schlüssel = deutscher Originaltext
local _, ns = ...
local E = ns.LocaleEN

-- Bankfenster (bag_bank.lua)
E["stray-Bank"] = "stray bank"
E["Ersetzt Blizzards Bankfenster durch ein eigenes Fenster im Stil der stray-Tasche: ein Abschnitt je Banktab bzw. Banktasche, Suche, Sortieren, „Alles einlagern“ und eine Leiste für die Banktaschen (einsetzen, herausnehmen, Plätze kaufen). Rechtsklick auf einen Gegenstand lagert ihn ein oder aus, wie gewohnt.\n\nWirkt nur, wenn auch „stray-Tasche“ eingeschaltet ist. Blizzards Bank bleibt unsichtbar im Hintergrund geöffnet; „Blizzard-Bank“ unten links im Fenster zeigt sie wieder (z. B. für die Kriegsmeute-Bank). Im Kampf oder bei Fehlern bleibt Blizzards Bank."] = "Replaces Blizzard's bank window with your own window in the style of the stray bag: one section per bank tab or bank bag, search, sorting, \"Deposit all\" and a bar for the bank bags (insert, remove, buy slots). Right-click on an item deposits or withdraws it as usual.\n\nOnly works while \"stray bag\" is also turned on. Blizzard's bank stays open invisibly in the background; \"Blizzard bank\" at the bottom left of the window shows it again (e.g. for the warband bank). In combat or on errors Blizzard's bank stays."
E["Spalten (Bank)"] = "Columns (bank)"
E["Wie viele Plätze im Bankfenster nebeneinander stehen. Ziehst du das Fenster unten rechts breiter oder schmaler, ändert sich dieser Wert mit."] = "How many slots sit side by side in the bank window. If you drag the window wider or narrower at the bottom right, this value changes with it."
E["Erst „stray-Bank“ einschalten (direkt darüber)."] = "Turn on \"stray bank\" first (directly above)."
E["Bankfenster: Blizzards Taschenknopf-Vorlage fehlt – es bleibt Blizzards Bank."] = "Bank window: Blizzard's bag button template is missing – Blizzard's bank stays."
E["Banktasche %d"] = "Bank bag %d"
E["Bankfach %d"] = "Bank tab %d"
E["Diese Bank hat noch keine Plätze."] = "This bank has no slots yet."
E["Höhe wieder automatisch: im Bearbeitungsmodus Shift+Rechtsklick auf das Bankfenster."] = "Height automatic again: in edit mode Shift+right-click on the bank window."

-- Kopf und Fuß
E["Sortieren"] = "Sort"
E["Einlagern"] = "Deposit"
E["Banktaschen"] = "Bank bags"
E["Blizzard-Bank"] = "Blizzard bank"
E["Bank sortieren"] = "Sort bank"
E["Sortiert die Plätze der Bank nach Blizzards Regeln. Geht nicht im Kampf."] = "Sorts the bank slots using Blizzard's rules. Not possible in combat."
E["Alles einlagern"] = "Deposit all"
E["Lagert passende Gegenstände aus deinen Taschen in die Bank ein (Blizzards „Alles einlagern“)."] = "Deposits suitable items from your bags into the bank (Blizzard's \"Deposit all\")."
E["Zeigt die Taschenplätze der Bank: Taschen einsetzen oder herausnehmen und weitere Plätze kaufen."] = "Shows the bank's bag slots: insert or remove bags and buy more slots."
E["Blizzards Bankfenster zeigen"] = "Show Blizzard's bank window"
E["Blendet Blizzards eigene Bank statt dieses Fensters ein (z. B. für die Kriegsmeute-Bank oder Tab-Einstellungen). Beim nächsten Besuch beim Bankier übernimmt stray wieder."] = "Shows Blizzard's own bank instead of this window (e.g. for the warband bank or tab settings). The next time you visit the banker, stray takes over again."

